python3 - <<'PY'
import os, re
root = "/bench/repo"
pat_store_pkg = re.compile(r'\bstore\.Memo\b')
# In store package (not store/db or store/test), Memo without prefix
pat_local = re.compile(r'\b(\*Memo|\[\]\*Memo|&Memo|Memo\s*\{|type Memo |create \*Memo|\[\].*Memo)\b')

hits = []
for dirpath, dirnames, filenames in os.walk(root):
    dirnames[:] = [d for d in dirnames if d not in ('.git', 'node_modules', 'web', 'proto/gen')]
    for fn in filenames:
        if not fn.endswith('.go'):
            continue
        path = os.path.join(dirpath, fn)
        rel = path[len(root)+1:]
        try:
            text = open(path, encoding='utf-8').read()
        except Exception:
            continue
        if '/store/db/' in rel or rel.startswith('store/db/'):
            if pat_store_pkg.search(text) or re.search(r'\*store\.Memo|\[\]\*store\.Memo', text):
                hits.append(rel)
        elif rel.startswith('store/') and not rel.startswith('store/test/') and not rel.startswith('store/db/'):
            # store package: look for Memo type usage, skip proto storepb.Memo
            if re.search(r'(?<!storepb\.)(?<!store\.)\bMemo\b', text) and ('type Memo' in text or '*Memo' in text or '[]*Memo' in text or '&Memo' in text):
                hits.append(rel)
        else:
            if pat_store_pkg.search(text):
                hits.append(rel)

for h in sorted(hits):
    print(h)
print('---COUNT---', len(hits))
PY

